import{_ as n,l as s,o as e,c as o,v as r,p as l,x as t,d as h,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"通用散列","description":"","frontmatter":{"title":"通用散列","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/universal-hashing.md","filePath":"cs/universal-hashing.md","lastUpdated":1789023840000}'),m={name:"cs/universal-hashing.md"};function c(_,a,u,f,A,C){const i=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="通用散列" tabindex="-1">通用散列 <a class="header-anchor" href="#通用散列" aria-label="Permalink to &quot;通用散列&quot;">​</a></h1><div class="epigraph"><p>函数从族里随机抽：任意一对不同键碰撞的概率 $\\le 1/m$；最坏输入对期望仍然成立。</p><footer>—— 据 Carter and Wegman, Universal Classes of Hash Functions, JCSS 1979；Cormen, Leiserson, Rivest and Stein 第 11 章整理</footer></div><p><a href="/cs/art-adaptive-radix">上一课</a> 结束字符串结构。主干<a href="/cs/hash-collision">散列碰撞</a> 已说明固定 \\(h\\) 可被对抗。<a href="/cs/string-hashing">字符串哈希</a> 用了随机模，未给族的定义。本课不画 ART 节点。缺口是 Carter–Wegman 通用散列：期望分析的合法前提。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>链地址、布隆、草图都要「碰撞不多」。对手若知道 \\(h\\)，可构造全撞一槽。通用族 \\(\\mathcal{H}\\)：对任意 \\(x\\neq y\\)，</p> \\[\\Pr_{h\\in\\mathcal{H}}[h(x)=h(y)] \\le 1/m \\]<p>（\\(m\\) 为槽数）。强通用（pairwise independent）还要求任意两槽对均匀。缺口是<strong>把随机性放在选 \\(h\\)，而不是假设输入随机</strong>。</p><p><span class="marginnote">Carter and Wegman, <em>JCSS</em>, 1979。多项式、乘法散列 \\(h_a(x)=\\lfloor m(ax\\bmod 2^w)/2^{w-d}\\rfloor\\) 等是常见构造。CLRS 第 11 章。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实践：程序启动抽 \\(a,b\\)，线性 \\(((ax+b)\\bmod p)\\bmod m\\)。证明两键碰撞化为一次均匀。多重独立（\\(k\\)-wise）给更好尾界，Count-Min 后课用。本课只钉 pairwise 级。</p>',10)),(e(),l(p,null,{default:t(()=>[d(i,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADV%5B%22%E4%BB%BB%E6%84%8F%E5%9B%BA%E5%AE%9A%20x%20%E2%89%A0%20y%22%5D%20--%3E%20H%5B%22%E9%9A%8F%E6%9C%BA%20h%20%E2%88%88%20H%22%5D%0A%20%20H%20--%3E%20COL%5B%22P(%E7%A2%B0%E6%92%9E)%20%E2%89%A4%201%2Fm%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与密码学哈希：通用散列不要求原像困难，只要碰撞概率；更快、键更短。不要混用 SHA 当布隆的 \\(k\\) 个索引——可以，但过重。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>期望链长：对固定键集，期望 \\(\\alpha\\) 与简单均匀假设相同，但现在对对抗输入也成立（期望对 \\(h\\)）。再散列换 \\(h\\) 即换族中另一员。实现须真随机种子，不能写死 \\(a=31\\)。</p><p>完美散列下一课在通用之上再消除碰撞（静态）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把有限域全部构造写完。一致性哈希解决的是槽增减，不是碰撞界。不要把本课写成 Transformer 位置编码。</p><p>后课默认：字典分析用通用族。静态零碰撞用完美散列。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>通用族：任意一对碰撞概率 \\(\\le 1/m\\)。</li><li>随机在函数，不在数据。</li><li>静态无碰撞字典是完美散列。</li><li>出处：Carter and Wegman, <em>JCSS</em>, 1979；Cormen et al.。</li></ul>',9))])}const b=n(m,[["render",c]]);export{S as __pageData,b as default};
